SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('sec.10 遗愿结算清单','sec.11 漆鸟择墓栖','sec.12 鲁伯特之泪','sec.2 听风手记','sec.3 如期归还','sec.4 我曾热爱过的世界','sec.5 眠','sec.6 伊卡洛斯综合征','sec.7 离海','sec.8 青色的窗','sec.9 该说的都不说','secret track by 他城','thinking','wasted land','zit','《全身而退》.2024.兰音.24bits.48khz','《哑谜》.2024.兰音.24bits.48khz','《好梦歌》.2024.兰音.24bits.48khz','《形神合一》.2024.兰音.24bits.48khz','《暮色浓妆》.2024.兰音.24bits.48khz','《比天高》.2024.兰音.24bits.48khz','《知夏》.2024.兰音.24bits.48khz','《破碎时间》.2024.兰音.24bits.48khz','《红烛泪》.2024.兰音.24bits.48khz','《镜中的陌生人》.2024.兰音.24bits.48khz','「救救我」','あの夏に嫌おれにた僕ら','ぐるぐる','オン・ステーヅ','ヒウマノイド美学,仿生人美学','一个人的零点','万象非众生','不停歇的旅途(合唱ver.)','不同频舞步','不夜城') ORDER BY sm.title,sm.album_id